function ____exports.drawWave(self, d, x, y, dir, t)
    local flick = 0.75 + 0.25 * math.sin(t * 20)
    do
        local g = 0
        while g < 3 do
            local gx = x - dir * g * 11
            local ga = flick * (1 - g * 0.32)
            local a0 = math.pi / 2 - dir * 1.25
            local a1 = math.pi / 2 + dir * 1.25
            ____exports.arc(
                nil,
                d,
                gx + dir * 8,
                y + 20,
                22,
                a0,
                a1,
                8,
                2.6,
                Palette.moonCyan,
                ga
            )
            ____exports.arc(
                nil,
                d,
                gx + dir * 13,
                y + 20,
                14,
                a0,
                a1,
                6,
                1.8,
                Palette.moonCyan,
                ga * 0.7
            )
            g = g + 1
        end
    end
    ____exports.dot(
        nil,
        d,
        x + dir * 8,
        y + 20,
        3,
        Palette.white,
        0.8 * flick
    )
end
